package com.mylifejournal.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.content.*;import android.widget.*;import org.json.*;import java.io.*;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends Activity{
 int bg=0xFFF5F6FA,ink=0xFF25283A,purple=0xFF6750A4; LinearLayout root,body;JournalDb db;String page="Home";JSONObject ui;
 public void onCreate(Bundle b){super.onCreate(b);db=new JournalDb(this);try{java.io.InputStream in=getAssets().open("ui.json");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[1024];int n;while((n=in.read(buf))>0)out.write(buf,0,n);ui=new JSONObject(out.toString("UTF-8"));bg=Color.parseColor(ui.optString("background","#F5F6FA"));purple=Color.parseColor(ui.optString("accent","#6750A4"));}catch(Exception e){ui=new JSONObject();}getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);show("Home");}
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
 TextView tx(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 void show(String p){page=p;root=col();root.setBackgroundColor(bg);setContentView(root);ScrollView sc=new ScrollView(this);body=col();pad(body,20,20,20,18);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 if(p.equals("Home"))home();else if(p.equals("Journal"))journal();else if(p.equals("Tasks"))tasks();else weekly();
 LinearLayout nav=row();nav.setBackgroundColor(Color.WHITE);pad(nav,5,8,5,8);String[] fallback={"Home","Journal","Tasks","Weekly"},is={"⌂","✎","✓","▥"};JSONArray configured=ui.optJSONArray("navigation");String[] ns=fallback;if(configured!=null&&configured.length()==4){ns=new String[4];for(int k=0;k<4;k++)ns[k]=configured.optString(k,fallback[k]);}for(int i=0;i<ns.length;i++){final String n=ns[i];LinearLayout it=col();it.setGravity(Gravity.CENTER);it.addView(tx(is[i],22,n.equals(p)?purple:0xFF888888,true));it.addView(tx(n,11,n.equals(p)?purple:0xFF888888,true));nav.addView(it,new LinearLayout.LayoutParams(0,-2,1));it.setOnClickListener(v->show(n));}root.addView(nav);}
 void title(String tag,String h,String sub){body.addView(tx(tag.toUpperCase(Locale.ROOT),11,purple,true));TextView t=tx(h,28,ink,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(5);body.addView(t,lp);TextView s=tx(sub,14,0xFF777B8C,false);lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(4);lp.bottomMargin=dp(18);body.addView(s,lp);}
 LinearLayout card(){LinearLayout c=col();c.setBackground(shape(Color.WHITE,20));pad(c,17,16,17,16);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(14);body.addView(c,lp);return c;}
 void btn(LinearLayout c,String s,Runnable r){TextView b=tx(s,14,Color.WHITE,true);b.setGravity(Gravity.CENTER);pad(b,12,13,12,13);b.setBackground(shape(purple,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);c.addView(b,lp);b.setOnClickListener(v->r.run());}
 void home(){JSONObject h=ui.optJSONObject("home");title("YOUR PERSONAL SPACE",h==null?"A little better, daily.":h.optString("headline","A little better, daily."),new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()));LinearLayout m=card();m.addView(tx("How are you feeling today?",17,ink,true));m.addView(tx("Check in with yourself — no judgement.",13,0xFF777777,false));LinearLayout rr=row();String[] em={"😞","😕","😐","🙂","😊"},lab={"Low","Meh","Okay","Good","Great"};for(int i=0;i<5;i++){final String v=lab[i];LinearLayout q=col();q.setGravity(Gravity.CENTER);q.addView(tx(em[i],24,ink,false));q.addView(tx(lab[i],10,0xFF777777,false));rr.addView(q,new LinearLayout.LayoutParams(0,-2,1));q.setOnClickListener(w->{db.mood(v);Toast.makeText(this,"Mood saved: "+v,0).show();});}LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(-1,-2);x.topMargin=dp(14);m.addView(rr,x);
 LinearLayout c=card();c.addView(tx("Today's progress",17,ink,true));c.addView(tx(db.done()+" of "+db.total()+" tasks completed",13,0xFF777777,false));ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(Math.max(1,db.total()));pb.setProgress(db.done());pb.setProgressTintList(android.content.res.ColorStateList.valueOf(purple));c.addView(pb,new LinearLayout.LayoutParams(-1,dp(8)));
 LinearLayout j=card();j.addView(tx("Make space for yourself",17,ink,true));j.addView(tx("A few honest lines can help you see your day clearly.",13,0xFF777777,false));btn(j,"＋  Write today's journal",()->show("Journal"));LinearLayout t=card();t.addView(tx("Your next small step",17,ink,true));t.addView(tx("Small steps count. Progress over perfection.",13,0xFF777777,false));btn(t,"View my tasks  →",()->show("Tasks"));}
 EditText edit(String hint,int lines){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(15);e.setMinLines(lines);e.setGravity(Gravity.TOP|Gravity.START);e.setBackground(shape(bg,12));pad(e,12,10,12,10);return e;}
 void journal(){title("DAILY REFLECTION","Dear journal…","No perfect words needed. Just be honest.");LinearLayout c=card();c.addView(tx("What went well today?",15,ink,true));EditText a=edit("One thing I'm grateful for…",3);c.addView(a);TextView h=tx("What felt difficult?",15,ink,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(15);c.addView(h,lp);EditText b=edit("Something on my mind…",3);c.addView(b);TextView t=tx("What will I try tomorrow?",15,ink,true);lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(15);c.addView(t,lp);EditText d=edit("One small next step…",2);c.addView(d);btn(c,"Save reflection",()->{db.journal(a.getText().toString(),b.getText().toString(),d.getText().toString());((InputMethodManager)getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(d.getWindowToken(),0);Toast.makeText(this,"Saved on this phone",0).show();show("Journal");});LinearLayout hst=card();hst.addView(tx("Recent reflection",16,ink,true));hst.addView(tx(db.latest().isEmpty()?"Your saved entry will appear here.":db.latest(),13,0xFF777777,false));}
 void tasks(){title("SMALL STEPS","Today's tasks","Build consistency, not pressure.");LinearLayout c=card();EditText e=edit("Add a small task…",1);c.addView(e);btn(c,"＋ Add task",()->{String s=e.getText().toString().trim();if(!s.isEmpty()){db.add(s);show("Tasks");}});for(JSONObject o:db.tasks()){try{int id=o.getInt("id");CheckBox cb=new CheckBox(this);cb.setText(o.getString("name"));cb.setTextSize(15);cb.setTextColor(ink);cb.setChecked(o.getInt("done")==1);c.addView(cb);cb.setOnCheckedChangeListener((v,on)->db.check(id,on));}catch(Exception ex){}}}
 void weekly(){title("LOOK BACK GENTLY","Your week at a glance","Progress isn't a straight line.");LinearLayout c=card();c.addView(tx("This week's check-in",18,ink,true));c.addView(tx("Journal entries saved: "+db.weekJournals(),15,ink,false));c.addView(tx("Tasks completed: "+db.weekDone(),15,ink,false));c.addView(tx("Tasks added: "+db.weekTasks(),15,ink,false));TextView p=tx("A reflection prompt",16,purple,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(18);c.addView(p,lp);c.addView(tx("What helped you feel more like yourself this week? What is one thing to carry into next week?",14,0xFF777777,false));}
}